Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).


(* [comment removed for export] *)
Definition FRH (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (FRD m s ret regs) (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (getr regs 24)).
(* [comment removed for export] *)
Definition PGDH (m : word -> option byte) (s w h : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 84)) (word_to_le_bytes 4 (Z_to_bv 64 0))) (Z_to_bv 64 (s - 88)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 84)) (word_to_le_bytes 4 (Z_to_bv 64 w))) (Z_to_bv 64 (s - 88)) (word_to_le_bytes 4 (Z_to_bv 64 h)).
(* [comment removed for export] *)
Definition SARH (m : word -> option byte) (s : Z) : word -> option byte :=
  wbytes m (Z_to_bv 64 (s - 144)) (word_to_le_bytes 8 (Z_to_bv 64 0)).

Section Segs.
Context {fx : FPState}.
Variable rom : word -> option byte.
Ltac fixv' v tac := lazymatch goal with |- msteps _ (mkst (regupd _ _ ?x) _ _ _) _ => first [ constr_eq x v | replace x with v by (symmetry; tac) ] end.
Ltac condS := pin; rewrite ?c_lts_Zs by lia; first [ apply Z.ltb_lt | apply Z.ltb_ge ]; lia.
Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

(* [comment removed for export] *)
Lemma hm_A : forall regs m (s pixd pixs sel : Z) (ret : word),
  (144 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 144)) 144 = true ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixd -> getr regs 11 = Z_to_bv 64 pixs ->
  getr regs 12 = Z_to_bv 64 sel ->
  exists regs',
    msteps SEGS (mkst regs (0x8fb4c : word) m rom) (mkst regs' (0x8f6d4 : word) (FRH m s ret regs) rom)
    /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 1 = Z_to_bv 64 0x8fb88 /\ getr regs' 9 = Z_to_bv 64 sel
    /\ getr regs' 18 = Z_to_bv 64 pixs /\ getr regs' 13 = Z_to_bv 64 (s - 128)
    /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 pixs /\ getr regs' 12 = Z_to_bv 64 sel
    /\ regs_agree (fun r => In r [1; 2; 9; 13; 18]%list) regs regs'.
Proof.
