(* [comment removed for export] *)
Lemma hm_B : forall regs m (s pixd pixs sel w h : Z),
  (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd < 2 ^ 64)%Z -> (1 <= pixs)%Z -> (pixs + 8 <= 2 ^ 64)%Z -> (0 <= w < 2 ^ 31)%Z -> (0 <= h < 2 ^ 31)%Z ->
  rdn SEGS (wbytes (wbytes m (Z_to_bv 64 (s - 84)) (word_to_le_bytes 4 (Z_to_bv 64 0))) (Z_to_bv 64 (s - 88)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
      (Z_to_bv 64 pixs) 4 = Some (Z_to_le_bytes 4 w) ->
  rdn SEGS (wbytes (wbytes (wbytes m (Z_to_bv 64 (s - 84)) (word_to_le_bytes 4 (Z_to_bv 64 0))) (Z_to_bv 64 (s - 88)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
      (Z_to_bv 64 (s - 84)) (word_to_le_bytes 4 (Z_to_bv 64 w))) (Z_to_bv 64 (pixs + 4)) 4 = Some (Z_to_le_bytes 4 h) ->
  store_ok SEGS m (Z_to_bv 64 (s - 88)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 10 = Z_to_bv 64 pixd -> getr regs 18 = Z_to_bv 64 pixs -> getr regs 9 = Z_to_bv 64 sel ->
  exists regs',
    msteps SEGS (mkst regs (0x8fb88 : word) m rom) (mkst regs' (0x92648 : word) (PGDH m s w h) rom)
    /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 1 = Z_to_bv 64 0x8fbbc /\ getr regs' 8 = Z_to_bv 64 pixd
    /\ getr regs' 10 = Z_to_bv 64 sel /\ getr regs' 11 = Z_to_bv 64 (s - 96) /\ getr regs' 12 = Z_to_bv 64 (s - 92)
    /\ getr regs' 13 = Z_to_bv 64 (s - 104) /\ getr regs' 14 = Z_to_bv 64 (s - 100)
