(* [comment removed for export] *)
Lemma hm_E : forall regs m (s sy sx : Z),
  (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= sy < 2 ^ 31)%Z -> (1 <= sx < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 96)) 4 = Some (Z_to_le_bytes 4 sy) -> rdn SEGS m (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 sx) ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  exists regs',
    msteps SEGS (mkst regs (0x8fbbc : word) m rom) (mkst regs' (0x8fc50 : word) m rom)
    /\ getr regs' 18 = Z_to_bv 64 0 /\ getr regs' 19 = Z_to_bv 64 1 /\ getr regs' 20 = Z_to_bv 64 2 /\ getr regs' 21 = Z_to_bv 64 (4 * 0)
    /\ getr regs' 22 = Z_to_bv 64 (- 0) /\ getr regs' 23 = Z_to_bv 64 0 /\ getr regs' 24 = Z_to_bv 64 (8 * 0)
    /\ getr regs' 10 = Z_to_bv 64 1 /\ getr regs' 11 = Z_to_bv 64 sx
    /\ regs_agree (fun r => In r [10; 11; 12; 18; 19; 20; 21; 22; 23; 24]%list) regs regs'.
Proof.
