(* [comment removed for export] *)
Lemma hm_L : forall regs m (s sy sx i j : Z),
  (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= sy < 2 ^ 31)%Z -> (1 <= sx < 2 ^ 31)%Z -> (0 <= i < sy)%Z -> (0 <= j < sx)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 96)) 4 = Some (Z_to_le_bytes 4 sy) -> rdn SEGS m (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 sx) ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  getr regs 18 = Z_to_bv 64 i -> getr regs 21 = Z_to_bv 64 (4 * j) -> getr regs 22 = Z_to_bv 64 (- j) -> getr regs 23 = Z_to_bv 64 j ->
  getr regs 24 = Z_to_bv 64 (8 * i) ->
  exists regs' (pc : word),
    msteps SEGS (mkst regs (0x8fc3c : word) m rom) (mkst regs' pc m rom)
    /\ ( ((j + 1 < sx)%Z /\ pc = (0x8fc50 : word) /\ getr regs' 18 = Z_to_bv 64 i /\ getr regs' 21 = Z_to_bv 64 (4 * (j + 1))
          /\ getr regs' 22 = Z_to_bv 64 (- (j + 1)) /\ getr regs' 23 = Z_to_bv 64 (j + 1) /\ getr regs' 24 = Z_to_bv 64 (8 * i))
       \/ ((j + 1 = sx)%Z /\ (i + 1 < sy)%Z /\ pc = (0x8fc50 : word) /\ getr regs' 18 = Z_to_bv 64 (i + 1) /\ getr regs' 21 = Z_to_bv 64 (4 * 0)
          /\ getr regs' 22 = Z_to_bv 64 (- 0) /\ getr regs' 23 = Z_to_bv 64 0 /\ getr regs' 24 = Z_to_bv 64 (8 * (i + 1)))
       \/ ((j + 1 = sx)%Z /\ (i + 1 = sy)%Z /\ pc = (0x8fc94 : word)) )
    /\ getr regs' 11 = Z_to_bv 64 sx
