(* [comment removed for export] *)
Lemma hm_M : forall regs m (sel data row i j c : Z),
  (0 <= sel)%Z -> (sel + 24 <= 2 ^ 64)%Z -> (0 <= data)%Z -> (data + 8 * i + 8 <= 2 ^ 64)%Z -> (0 <= row)%Z -> (row + 4 * j + 4 <= 2 ^ 64)%Z ->
  (0 <= i < 2 ^ 31)%Z -> (0 <= j < 2 ^ 31)%Z -> (0 <= c < 2 ^ 31)%Z -> c <> 1%Z -> c <> 2%Z ->
  rdn SEGS m (Z_to_bv 64 (sel + 16)) 8 = Some (Z_to_le_bytes 8 data) ->
  rdn SEGS m (Z_to_bv 64 (data + 8 * i)) 8 = Some (Z_to_le_bytes 8 row) ->
  rdn SEGS m (Z_to_bv 64 (row + 4 * j)) 4 = Some (Z_to_le_bytes 4 c) ->
  getr regs 9 = Z_to_bv 64 sel -> getr regs 19 = Z_to_bv 64 1 -> getr regs 20 = Z_to_bv 64 2 -> getr regs 21 = Z_to_bv 64 (4 * j) ->
  getr regs 24 = Z_to_bv 64 (8 * i) ->
  exists regs',
    msteps SEGS (mkst regs (0x8fc50 : word) m rom) (mkst regs' (0x8fc3c : word) m rom)
    /\ regs_agree (fun r => In r [11]%list) regs regs'.
Proof.
