(* [comment removed for export] *)
Lemma hm_H2n : forall regs m (sel data row i j : Z),
  (0 <= sel)%Z -> (sel + 24 <= 2 ^ 64)%Z -> (0 <= data)%Z -> (data + 8 * i + 8 <= 2 ^ 64)%Z -> (0 <= row)%Z -> (row + 4 * j + 4 <= 2 ^ 64)%Z ->
  (0 <= i < 2 ^ 31)%Z -> (0 <= j < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (sel + 16)) 8 = Some (Z_to_le_bytes 8 data) ->
  rdn SEGS m (Z_to_bv 64 (data + 8 * i)) 8 = Some (Z_to_le_bytes 8 row) ->
  rdn SEGS m (Z_to_bv 64 (row + 4 * j)) 4 = Some (Z_to_le_bytes 4 2) ->
  getr regs 9 = Z_to_bv 64 sel -> getr regs 19 = Z_to_bv 64 1 -> getr regs 20 = Z_to_bv 64 2 ->
  getr regs 21 = Z_to_bv 64 (4 * j) -> getr regs 24 = Z_to_bv 64 (8 * i) -> getr regs 10 = Z_to_bv 64 0 ->
  exists regs',
    msteps SEGS (mkst regs (0x8fc50 : word) m rom) (mkst regs' (0x8fc0c : word) m rom)
    /\ getr regs' 15 = Z_to_bv 64 2 /\ regs_agree (fun r => In r [11; 15]%list) regs regs'.
Proof.
