Lemma hm_S : forall regs m (s i j pixd pixt w h cx cy op : Z),
  (144 <= s)%Z -> (s < 2 ^ 64)%Z ->
  (0 <= i < 2 ^ 30)%Z -> (0 <= j < 2 ^ 30)%Z -> (0 <= cx < 2 ^ 30)%Z -> (0 <= cy < 2 ^ 30)%Z -> (0 <= w < 2 ^ 31)%Z -> (0 <= h < 2 ^ 31)%Z ->
  (0 <= pixt < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 100)) 4 = Some (Z_to_le_bytes 4 cx) -> rdn SEGS m (Z_to_bv 64 (s - 104)) 4 = Some (Z_to_le_bytes 4 cy) ->
  rdn SEGS m (Z_to_bv 64 (s - 84)) 4 = Some (Z_to_le_bytes 4 w) -> rdn SEGS m (Z_to_bv 64 (s - 88)) 4 = Some (Z_to_le_bytes 4 h) ->
  rdn SEGS m (Z_to_bv 64 (s - 128)) 8 = Some (Z_to_le_bytes 8 pixt) ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 8 = Z_to_bv 64 pixd -> getr regs 18 = Z_to_bv 64 i -> getr regs 22 = Z_to_bv 64 (- j) ->
  getr regs 15 = Z_to_bv 64 op ->
  exists regs',
    msteps SEGS (mkst regs (0x8fc0c : word) m rom) (mkst regs' (0x797ac : word) (SARH m s) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x8fc38 /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 (cx - j)
    /\ getr regs' 12 = Z_to_bv 64 (cy - i) /\ getr regs' 13 = Z_to_bv 64 w /\ getr regs' 14 = Z_to_bv 64 h
    /\ getr regs' 15 = Z_to_bv 64 op /\ getr regs' 16 = Z_to_bv 64 pixt /\ getr regs' 17 = Z_to_bv 64 0
    /\ regs_agree (fun r => In r [1; 10; 11; 12; 13; 14; 16; 17]%list) regs regs'.
Proof.
