Lemma hm_X1c : forall regs m (s pixd xp h : Z), (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= xp < 2 ^ 31)%Z -> (0 <= h < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 108)) 4 = Some (Z_to_le_bytes 4 xp) -> rdn SEGS m (Z_to_bv 64 (s - 88)) 4 = Some (Z_to_le_bytes 4 h) ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 8 = true -> getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 8 = Z_to_bv 64 pixd ->
  exists regs', msteps SEGS (mkst regs (0x8fcac : word) m rom) (mkst regs' (0x797ac : word) (SARH m s) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x8fcd8 /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 12 = Z_to_bv 64 0
    /\ getr regs' 13 = Z_to_bv 64 xp /\ getr regs' 14 = Z_to_bv 64 h /\ getr regs' 15 = Z_to_bv 64 0 /\ getr regs' 16 = Z_to_bv 64 0
    /\ getr regs' 17 = Z_to_bv 64 0 /\ regs_agree (fun r => In r [1; 10; 11; 12; 13; 14; 15; 16; 17]%list) regs regs'.
Proof.
