Lemma hm_X3c : forall regs m (s pixd yp w : Z), (144 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= yp < 2 ^ 31)%Z -> (0 <= w < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 112)) 4 = Some (Z_to_le_bytes 4 yp) -> rdn SEGS m (Z_to_bv 64 (s - 84)) 4 = Some (Z_to_le_bytes 4 w) ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 8 = true -> getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 8 = Z_to_bv 64 pixd ->
  exists regs', msteps SEGS (mkst regs (0x8fd08 : word) m rom) (mkst regs' (0x797ac : word) (SARH m s) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x8fd34 /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 12 = Z_to_bv 64 0
    /\ getr regs' 13 = Z_to_bv 64 w /\ getr regs' 14 = Z_to_bv 64 yp /\ getr regs' 15 = Z_to_bv 64 0 /\ getr regs' 16 = Z_to_bv 64 0
    /\ getr regs' 17 = Z_to_bv 64 0 /\ regs_agree (fun r => In r [1; 10; 11; 12; 13; 14; 15; 16; 17]%list) regs regs'.
